272	  private async contextViaCli(root: string, task: string, limit: number): Promise<ContextPacket> {
273	    const binary = this.resolvedBinary || this.resolveBinary();
274	    if (!binary) {
275	      throw new Error(
276	        "CallSieve binary not found. Set callsieve.binaryPath or install callsieve on PATH.",
277	      );
278	    }
279	    this.resolvedBinary = binary;
280	    return new Promise((resolve, reject) => {
281	      const proc = spawn(
282	        binary,
283	        ["agent-context", root, task, "--format", "json", "--limit", String(limit)],
284	        { stdio: ["ignore", "pipe", "pipe"] },
285	      );
286	      let stdout = "";
287	      let stderr = "";
288	      proc.stdout.setEncoding("utf8");
289	      proc.stderr.setEncoding("utf8");
290	      proc.stdout.on("data", (chunk: string) => (stdout += chunk));
291	      proc.stderr.on("data", (chunk: string) => (stderr += chunk));
292	      proc.on("error", (err) => reject(err));
293	      proc.on("close", (code) => {
294	        if (code !== 0) {
295	          reject(new Error(`callsieve agent-context exited ${code}: ${stderr.trim()}`));
296	          return;
297	        }
298	        try {
299	          const parsed = JSON.parse(stdout);
300	          resolve(parseAgentContextOutput(parsed, task, root));
301	        } catch (err) {
302	          reject(err instanceof Error ? err : new Error(String(err)));
303	        }
304	      });
305	    });
306	  }
